(OutSystems.Model.IESpace eSpace) => {
    
    /*** creating IMobileTheme 'ClaudeSheet' ***/
    var claudeSheet = eSpace.CreateMobileTheme("ClaudeSheet");
    claudeSheet.AddOrUpdateThemeValues(new Dictionary<ThemeProperty, string> {
        {ThemeProperty.PrimaryColor, "#dc3023"},
        {ThemeProperty.AppPrimaryColor, "#dc3023"},
        {ThemeProperty.SecondaryColor, "#dc3023"},
        {ThemeProperty.CreatedWithoutCustomCSS, "true"},
    });
    var outSystemsUI = eSpace.References.Named("OutSystemsUI");
    var outSystemsUI2 = outSystemsUI.MobileThemes.Named("OutSystemsUI");
    claudeSheet.BaseTheme = outSystemsUI2;
    claudeSheet.Columns = 12; // default value
    claudeSheet.ColumnWidth = 60; // default value
    claudeSheet.Description = "Application theme";
    claudeSheet.Folder = null; // default value
    claudeSheet.Footer = null; // default value
    claudeSheet.GridType = OutSystems.Model.Enumerations.GridType.Fluid;
    claudeSheet.GutterWidth = 20; // default value
    claudeSheet.GutterWidthPercentage = 30; // default value
    claudeSheet.Header = null; // default value
    claudeSheet.IconLibrary = null;
    var layouts = eSpace.MobileFlows.Named("Layouts");
    var layoutTopMenu = layouts.Nodes.OfType<OutSystems.Model.UI.Mobile.IMobileBlock>().Named("LayoutTopMenu");
    claudeSheet.Layout = layoutTopMenu;
    claudeSheet.MaxWidth = 1280;
    var common = eSpace.MobileFlows.Named("Common");
    var menu = common.Nodes.OfType<OutSystems.Model.UI.Mobile.IMobileBlock>().Named("Menu");
    claudeSheet.Menu = menu;
    claudeSheet.MinWidth = null; // default value
    claudeSheet.Public = true;
    claudeSheet.Shareable = true;
    claudeSheet.StyleSheet = "/* ===================================================================== */\r\n/*  The following CSS was created using Theme Editor.                    */\r\n/*  To modify this CSS, click \"Open Theme Editor\".                       */\r\n/* ===================================================================== */\r\n\r\n/* ===================================================================== */\r\n/*  Root - CSS Variables                                                 */\r\n/* ===================================================================== */\r\n\r\n:root {\r\n\t\r\n    /* Color - Brand */\r\n    --color-primary: #dc3023;\r\n    --color-secondary: #dc3023;\r\n\r\n    --color-primary-hover: #a5241a;\r\n    --color-primary-selected: rgba(220, 48, 35, .12);\r\n\t\r\n    /* Dark Theme */\r\n    --background-dark-theme: rgba(255, 255, 255, .1);\r\n    --background-dark-theme-hover: rgba(255, 255, 255, .2);\r\n}\r\n\r\n\r\n.ms-theme-start { }\n\n/* MySheet - status colours and calendar day classes (US-000) */\n:root {\n    --sheet-confirmed: #2e9e5b;\n    --sheet-dayoff: #6b5bd2;\n    --sheet-holiday: #e0a100;\n    --sheet-pending: #e05a47;\n    --sheet-accent: var(--color-primary);\n    --sheet-card: #ffffff;\n    --sheet-bg: #f4f5f7;\n}\n\n.day-confirmed { background-color: var(--sheet-confirmed); border-color: var(--sheet-confirmed); color: #ffffff; }\n.day-off { background-color: var(--sheet-dayoff); border-color: var(--sheet-dayoff); color: #ffffff; }\n.day-holiday { background-color: var(--sheet-holiday); border-color: var(--sheet-holiday); color: #ffffff; }\n.day-pending { background-color: var(--sheet-card); border: 1px dashed var(--sheet-pending); color: var(--sheet-pending); }\n.day-future { background-color: var(--sheet-card); color: var(--color-neutral-6); }\n.day-weekend { background-color: var(--sheet-bg); color: var(--color-neutral-6); }\n\n/* MySheet - TotalHoursMonth block (US1) */\n:root {\n    --sheet-surface-dark: #1E1E1E;\n    --sheet-track: #2A2A2A;\n    --sheet-muted: #9E9E9E;\n}\n.sheet-total { display: flex; flex-direction: column; align-items: center; gap: 16px; padding: 24px; background-color: var(--sheet-surface-dark); border-radius: 8px; }\n.sheet-total__circle { width: 160px; height: 160px; }\n.phone .sheet-total__circle { width: 120px; height: 120px; }\n.sheet-total__inner { display: flex; flex-direction: column; align-items: center; justify-content: center; line-height: 1.2; }\n.sheet-total__label { font-size: 12px; color: var(--sheet-muted); }\n.sheet-total__value { font-size: 28px; font-weight: 700; color: #FFFFFF; }\n.phone .sheet-total__value { font-size: 22px; }\n.sheet-total__caption { font-size: 12px; color: var(--sheet-muted); text-align: center; }\n.sheet-total--loading .sheet-total__value,\n.sheet-total--loading .sheet-total__caption { color: transparent; border-radius: 4px; background: linear-gradient(90deg, var(--sheet-track) 25%, #3A3A3A 50%, var(--sheet-track) 75%); background-size: 200% 100%; animation: sheet-shimmer 1.2s ease-in-out infinite; }\n@keyframes sheet-shimmer { 0% { background-position: 200% 0; } 100% { background-position: -200% 0; } }\n\n.sheet-cal-start { }\n\n/* MySheet - HoursCalendar block (US2) */\n.sheet-cal { --sheet-dayoff: #2f7fd8; --sheet-holiday: #8a4fd1; width: 100%; padding: 16px; border-radius: 8px; background-color: var(--sheet-surface-dark); color: #FFFFFF; }\n.sheet-cal__header { display: flex; flex-wrap: nowrap; align-items: center; justify-content: space-between; gap: 8px; margin-bottom: 12px; }\n.sheet-cal__title { flex: 1 1 auto; min-width: 0; text-align: center; font-size: 18px; font-weight: 700; color: var(--sheet-accent); }\n.sheet-cal__arrow { flex: 0 0 auto; display: inline-flex; align-items: center; justify-content: center; width: 36px; height: 36px; padding: 0; border: 1px solid #3A3A3A; border-radius: 6px; background: transparent; color: #FFFFFF; cursor: pointer; }\n.sheet-cal__arrow:hover { background-color: var(--sheet-track); }\n.sheet-cal__arrow:focus-visible, .sheet-cal__day:focus-visible { outline: 2px solid #FFFFFF; outline-offset: 2px; }\n.sheet-cal__weekdays, .sheet-cal__grid { display: grid; grid-template-columns: repeat(7, minmax(0, 1fr)); gap: 6px; }\n.sheet-cal__weekdays { margin-bottom: 6px; }\n.sheet-cal__weekday { text-align: center; font-size: 12px; color: var(--sheet-muted); }\n.sheet-cal__grid > * { min-width: 0; }\n.sheet-cal__blank, .sheet-cal__day { aspect-ratio: 1 / 1; border-radius: 6px; }\n.sheet-cal__day { display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 3px; width: 100%; min-width: 0; height: auto; padding: 0; border: 0; background-color: transparent; color: #FFFFFF; font-size: 14px; font-weight: 600; line-height: 1; cursor: pointer; }\n.sheet-cal__day.is-readonly { cursor: default; }\n.sheet-cal__day.is-editable:hover { box-shadow: 0 0 0 2px rgba(255, 255, 255, .4); }\n.sheet-cal .day-confirmed { background-color: var(--sheet-confirmed); border: 0; color: #FFFFFF; }\n.sheet-cal .day-off { background-color: var(--sheet-dayoff); border: 0; color: #FFFFFF; }\n.sheet-cal .day-holiday { background-color: var(--sheet-holiday); border: 0; color: #FFFFFF; }\n.sheet-cal .day-pending { background-color: var(--sheet-pending); border: 0; color: #FFFFFF; }\n.sheet-cal .day-future { background-color: transparent; color: #FFFFFF; }\n.sheet-cal .day-weekend { background-color: transparent; color: var(--sheet-muted); }\n.sheet-cal__dot { width: 5px; height: 5px; border-radius: 50%; visibility: hidden; }\n.sheet-cal__dot.has-record { visibility: visible; background-color: var(--color-primary); }\n.sheet-cal__dot.is-today { visibility: visible; background-color: #FFFFFF; }\n.sheet-cal--loading .sheet-cal__grid { opacity: .4; }\n.sheet-cal__footer { display: flex; justify-content: center; margin-top: 16px; }\n.sheet-cal__fill[disabled] { background-color: #3A3A3A; border-color: #3A3A3A; color: var(--sheet-muted); cursor: not-allowed; }\n.sheet-popup { width: calc(100% - 32px); max-width: 560px; }\n.sheet-popup__title { margin-bottom: 12px; font-size: 18px; font-weight: 700; }\n.sheet-popup__hint { margin: 8px 0; font-size: 13px; color: var(--color-neutral-7); }\n.sheet-popup__warning { margin: 8px 0; padding: 8px 12px; border-radius: 6px; background-color: #FFF4D6; color: #7A4F00; font-size: 13px; }\n.sheet-popup__error { margin: 8px 0; padding: 8px 12px; border-radius: 6px; background-color: #FDE8E6; color: #B42318; font-size: 13px; }\n.sheet-popup__actions { display: flex; flex-wrap: wrap; justify-content: flex-end; gap: 8px; margin-top: 16px; }\n.sheet-editor__line { display: grid; grid-template-columns: 1fr auto; gap: 8px 12px; padding: 10px 0; border-bottom: 1px solid var(--color-neutral-4); }\n.sheet-editor__client { font-weight: 700; }\n.sheet-editor__name { font-size: 13px; color: var(--color-neutral-7); }\n.sheet-editor__time { display: flex; align-items: center; gap: 4px; }\n.sheet-editor__time select { width: auto; min-width: 64px; }\n.sheet-editor__desc { grid-column: 1 / -1; }\n.sheet-editor__total { margin-top: 8px; text-align: right; font-weight: 700; }\n.sheet-fill__field { margin-bottom: 12px; }\n.sheet-fill__label { margin-bottom: 4px; font-size: 13px; font-weight: 600; }\n.phone .sheet-cal { padding: 12px; }\n.phone .sheet-cal__weekdays, .phone .sheet-cal__grid { gap: 4px; }\n.phone .sheet-cal__day { font-size: 12px; }\n.phone .sheet-cal__arrow { width: 32px; height: 32px; }\n.phone .sheet-editor__line { grid-template-columns: 1fr; }\n";
}
